    "name": "Gouache Layer Country",
    "glsl": "// knobs: A=paint texture B=layer depth C=palette warmth\nfloat h21(vec2 p){ p = fract(p*vec2(127.1, 311.7)); p += dot(p, p + 34.7); return fract(p.x*p.y); }\nfloat vn(vec2 p){\n  vec2 i = floor(p), f = fract(p);\n  f = f*f*(3.0 - 2.0*f);\n  float a = h21(i), b = h21(i+vec2(1.0,0.0)), c = h21(i+vec2(0.0,1.0)), d = h21(i+vec2(1.0,1.0));\n  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);\n}\nfloat fbm(vec2 p){\n  float s = 0.0, a = 0.55;\n  for(int i = 0; i < 4; i++){ s += a*vn(p); p = p*2.03 + vec2(1.7, 9.2); a *= 0.5; }\n  return s;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord){\n  vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;\n  vec2 mo = vec2(0.30, 0.26);\n  if(dot(iMouse.xy, iMouse.xy) > 1.0) mo = (iMouse.xy - 0.5*iResolution.xy)/iResolution.y;\n  float t = iTime;\n  float aa = 2.0/iResolution.y;\n  float paint = 0.25 + 0.75*iKnobA;\n  vec3 warm = mix(vec3(0.42, 0.20, 0.34), vec3(0.62, 0.30, 0.14), iKnobC);\n\n  float s = clamp(uv.y*1.2 + 0.35, 0.0, 0.999);\n  float sq = floor(s*4.0)/3.0;\n  vec3 col = mix(warm*0.55, vec3(0.055, 0.050, 0.095), sq);\n  float tx = fbm(uv*vec2(3.0, 6.0) + vec2(0.03*t, 0.0));\n  float streak = sin(uv.x*70.0 + 9.0*tx)*0.5 + 0.5;\n  col *= 0.86 + 0.30*tx*paint + 0.10*streak*paint;\n\n  vec2 sc = vec2(mo.x*0.9, clamp(mo.y, -0.05, 0.42));\n  float sd = length(uv - sc);\n  col = mix(col, vec3(0.98, 0.62, 0.22)*0.60, (1.0 - smoothstep(0.20, 0.34, sd))*0.50);\n  col = mix(col, vec3(1.00, 0.74, 0.30), 1.0 - smoothstep(0.113, 0.121, sd));\n\n  float n = floor(2.0 + 3.0*iKnobB);\n  for(int i = 0; i < 5; i++){\n    float fi = float(i);\n    if(fi >= n) break;\n    float dep = fi/max(n - 1.0, 1.0);\n    vec2 q = uv + vec2(mo.x*(0.03 + 0.14*dep) + 0.012*dep*sin(t*0.2), 0.0);\n    float ridge = -0.02 - 0.34*dep + (0.10 - 0.05*dep)*fbm(vec2(q.x*(1.1 + 1.9*dep) + fi*7.3, fi*3.1));\n    ridge += 0.010*paint*(vn(vec2(q.x*90.0, fi*5.0)) - 0.5);\n    float cov = 1.0 - smoothstep(0.0, aa, q.y - ridge);\n    vec3 base = mix(mix(vec3(0.14, 0.13, 0.22), warm, 0.35), vec3(0.045, 0.048, 0.070), dep);\n    float ptx = fbm(q*vec2(5.0, 12.0) + fi*11.0);\n    float brs = sin((q.x + q.y*0.3)*120.0 + 7.0*ptx)*0.5 + 0.5;\n    float v = floor((0.78 + 0.42*ptx*paint + 0.16*brs*paint)*4.0)/4.0;\n    col = mix(col, base*v, cov);\n    float rim = smoothstep(0.020, 0.0, abs(q.y - ridge))*(1.0 - dep);\n    col = mix(col, vec3(1.00, 0.66, 0.28), rim*cov*0.38);\n  }\n\n  col *= 0.94 + 0.10*fbm(uv*40.0)*paint;\n  col *= 1.0 - 0.36*dot(uv, uv);\n  fragColor = vec4(max(col, 0.0), 1.0);\n}",
