    "name": "Emet / Met · the single letter",
    "glsl": "float bit(float n,float a){ return mod(floor(n/pow(2.0,a)),2.0); }\nfloat field(vec2 uv,float t){\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float rings=0.5+0.5*sin(r*16.0 - t*1.5 + sin(a*3.0));\n  float core=exp(-r*2.6);\n  return clamp(core*1.6 + rings*0.55*smoothstep(1.15,0.05,r),0.0,1.0);\n}\nvoid mainImage(out vec4 fragColor,in vec2 fragCoord){\n  float t=iTime;\n  float cs=11.0;\n  vec2 cell=floor(fragCoord/cs);\n  vec2 cc=(cell+0.5)*cs;\n  vec2 uv=(cc-0.5*iResolution.xy)/iResolution.y;\n  vec2 uvp=(fragCoord-0.5*iResolution.xy)/iResolution.y;\n  float lum=field(uv,t);\n  float n=0.0;\n  if(lum>0.10) n=4096.0;\n  if(lum>0.32) n=4357252.0;\n  if(lum>0.58) n=33554431.0;\n  float rc=length(uv);\n  float live=step(0.5,0.5+0.5*sin(t*0.8));\n  if(rc<0.17){ n = mix(4096.0, 33080881.0, live); }\n  vec2 pc=fract(fragCoord/cs);\n  float g=bit(n, floor(pc.x*5.0)+5.0*floor((1.0-pc.y)*5.0));\n  vec3 ink=vec3(0.04,0.03,0.06);\n  vec3 amber=vec3(1.0,0.72,0.26);\n  vec3 rust=vec3(0.88,0.38,0.16);\n  vec3 gcol=mix(rust,amber,lum);\n  if(rc<0.17) gcol=mix(vec3(0.30,0.32,0.42), amber, live);\n  vec3 base = gcol*lum;\n  vec3 col=ink + base*(0.34+0.66*g) + amber*g*0.3*lum;\n  col += amber*exp(-rc*2.2)*0.3;\n  col*=0.9+0.1*sin(fragCoord.y*0.35+t);\n  fragColor=vec4(clamp(col,0.0,1.0),1.0);\n}",
