    "name": "The Aperture · halftone plate",
    "glsl": "mat2 rot(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}\nfloat orb(vec2 uv,float t){\n  float r=length(uv);\n  float pupil=0.18+0.03*sin(t*0.7);\n  float iris=smoothstep(pupil,pupil+0.02,r);   // dark pupil swallows the center\n  float glow=exp(-r*2.4)*1.3;\n  float rings=0.5+0.5*sin(r*26.0 - t*1.6);\n  return clamp(glow*iris + rings*0.25*smoothstep(0.95,0.15,r)*iris,0.0,1.0);\n}\nvoid mainImage(out vec4 fragColor,in vec2 fragCoord){\n  float t=iTime;\n  vec2 uv=(fragCoord-0.5*iResolution.xy)/iResolution.y;\n  float lum=orb(uv,t);\n  float ang=radians(18.0)+0.10*sin(t*0.2);\n  vec2 g=rot(ang)*(fragCoord/iResolution.y);\n  float grid=95.0;\n  vec2 cp=fract(g*grid)-0.5;\n  float d=length(cp);\n  float radius=0.52*sqrt(lum);\n  float dot=smoothstep(radius+0.03,radius-0.03,d);\n  vec3 ink=vec3(0.03,0.02,0.05);\n  vec3 magenta=vec3(1.0,0.31,0.64);\n  float rr=length(uv);\n  float rim=exp(-42.0*abs(rr-(0.18+0.03*sin(t*0.7))));\n  vec3 spectral=0.5+0.5*cos(6.2831*(rr*3.0 - t*0.3)+vec3(0.0,2.09,4.18)); // the one spectral flare\n  vec3 col=ink + magenta*dot*(0.5+0.6*lum);\n  col+=spectral*rim*0.6;\n  col=pow(clamp(col,0.0,1.0),vec3(0.85));\n  fragColor=vec4(col,1.0);\n}",
