    "name": "Crystal City · the impossible fold",
    "glsl": "mat2 rot(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}\nvoid mainImage(out vec4 fragColor,in vec2 fragCoord){\n  float t=iTime;\n  vec2 uv=(fragCoord-0.5*iResolution.xy)/iResolution.y;\n  uv*=1.4;\n  float acc=0.0, edge=0.0;\n  vec2 p=uv;\n  for(int i=0;i<6;i++){\n    p=abs(p)-0.5;\n    p*=rot(0.4+0.05*sin(t*0.2)+float(i)*0.3);\n    p*=1.12;\n    float d=abs(p.x)+abs(p.y);                    // diamond metric -> crystal facet\n    acc+=exp(-8.0*abs(fract(d*3.0)-0.5));          // op-art parallel line-work\n    edge+=exp(-20.0*abs(p.x*p.y));                 // faceted crossing edges\n  }\n  float phase=acc*1.3 - t*0.4;                     // a fold count that never quite agrees\n  vec3 ink=vec3(0.03,0.02,0.06);\n  vec3 violet=vec3(0.55,0.35,0.85);\n  vec3 cyan=vec3(0.31,0.86,0.94);\n  vec3 col=ink;\n  col+=mix(violet,cyan,0.5+0.5*sin(phase))*acc*0.40;\n  col+=violet*edge*0.5;\n  col*=1.0-0.3*length(uv);\n  col=pow(clamp(col,0.0,1.0),vec3(0.85));\n  fragColor=vec4(col,1.0);\n}",
