    "name": "Membrane · the biomechanical crosshatch",
    "glsl": "mat2 rot(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}\nfloat hash(vec2 p){p=fract(p*vec2(123.34,345.45));p+=dot(p,p+34.345);return fract(p.x*p.y);}\nfloat vnoise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);\n  float a=hash(i),b=hash(i+vec2(1.0,0.0)),c=hash(i+vec2(0.0,1.0)),d=hash(i+vec2(1.0,1.0));\n  return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}\nfloat fbm(vec2 p){float s=0.0,a=0.5;for(int i=0;i<5;i++){s+=a*vnoise(p);p=rot(0.7)*p*2.02;a*=0.5;}return s;}\nfloat lines(vec2 uv,float ang,float freq){\n  vec2 q=rot(ang)*uv;\n  float s=abs(fract(q.y*freq)-0.5)*2.0;\n  return 1.0-smoothstep(0.0,0.4,s);\n}\nvoid mainImage(out vec4 fragColor,in vec2 fragCoord){\n  float t=iTime;\n  vec2 uv=(fragCoord-0.5*iResolution.xy)/iResolution.y;\n  vec2 p=uv*2.0;\n  vec2 w=vec2(fbm(p+vec2(0.0,t*0.1)), fbm(p+vec2(3.1,-t*0.08)));\n  float body=fbm(p+2.5*w);\n  float vein=pow(1.0-abs(fbm(p*1.7+2.5*w)-0.5)*2.0,3.0);\n  float tone=clamp(body*1.1 + vein*0.4,0.0,1.0);\n  float dark=1.0-tone;\n  vec2 hv=uv+0.15*w;                                // hatch rides the breathing tissue\n  float ink4=0.0;\n  ink4=max(ink4, lines(hv,0.0 ,60.0)*step(0.15,dark));\n  ink4=max(ink4, lines(hv,1.57,60.0)*step(0.38,dark));\n  ink4=max(ink4, lines(hv,0.78,80.0)*step(0.58,dark));\n  ink4=max(ink4, lines(hv,2.36,80.0)*step(0.76,dark));\n  vec3 ink=vec3(0.03,0.02,0.06);\n  vec3 magenta=vec3(1.0,0.31,0.64);\n  vec3 violet=vec3(0.55,0.35,0.85);\n  vec3 col=ink;\n  col+=violet*body*0.10;\n  col+=mix(violet,magenta,tone)*ink4*(0.55+0.6*vein);\n  col*=0.9+0.1*sin(t*0.8+body*6.28);\n  col=pow(clamp(col,0.0,1.0),vec3(0.9));\n  fragColor=vec4(col,1.0);\n}",
